def compute(vars):
    old_value = vars["v1"]  # 2018
    new_value = vars["v2"]  # 2019
    change = new_value - old_value
    return {
        "value": change,
        "trace": {
            "old_value_2018": old_value,
            "new_value_2019": new_value,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
